---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Feedback sheet: Rate an answer and tell the agent what missed.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change feedback-sheet.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './feedback-sheet.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'bare', className]} data-c="feedback-sheet" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="fbx">
  <p class="msg">I tightened the hero spacing to 24px and swapped the CTA to the accent blue. The card grid now wraps at 720px.</p>
  <div class="fbx-bar">
    <button class="ib fbx-up" aria-label="Good answer" data-tip="Good answer"><svg class="i s"><use href="#i-up-thumb"/></svg></button>
    <button class="ib fbx-dn" aria-label="Bad answer" data-tip="Bad answer"><svg class="i s"><use href="#i-down-thumb"/></svg></button>
    <span class="fbx-st muted"></span>
  </div>
  <div class="fold shut fbx-box"><div><div class="fbx-in panel keep">
    <div class="fbx-q">What went wrong?</div>
    <div class="fbx-ch"><button class="chip sm">Wrong spacing</button><button class="chip sm">Ignored my tokens</button><button class="chip sm">Too many changes</button><button class="chip sm">Broke the layout</button></div>
    <textarea class="fbx-ta" rows="2" placeholder="Anything else the agent should know"></textarea>
    <div class="fbx-f"><span class="muted fbx-n">Shared with the agent for this project</span><button class="pill ghost sm fbx-x">Cancel</button><button class="pill primary sm fbx-go" disabled>Send</button></div>
  </div></div></div>
</div>
  </Fragment></div>
</div>
<script>
  import './feedback-sheet.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Feedback sheet ---------- */
.fbx{display:flex;flex-direction:column;gap:var(--dm-s-2)}
/* the first thumb's icon starts where the answer does */
.fbx-bar{display:flex;align-items:center;gap:2px;margin-left:-8px}
.fbx-bar .ib svg{transition:transform .45s var(--dm-ease)}
.fbx-bar .ib.on svg{transform:rotate(-8deg)}
/* nothing in the row shrinks or swells on a click (owner, 18 Nov): a rated thumb only tilts */
.fbx-bar .ib:active,.fbx-f .pill.ghost:active{transform:none}
/* the thumbs sit on the stage, where --dm-row is the stage's own colour: the bar sets --dm-row to a quiet 5% of the text colour, as
   the other cards on the stage do, so the thumbs keep the one shared hover */
.fbx-bar{--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
:root[data-style="clean"] .fbx-bar .ib:active,:root [data-style="clean"] .fbx-bar .ib:active,:root [data-style="clean"].fbx-bar .ib:active{transform:none}
.fbx-dn.on{background:var(--dm-bad-bg);color:var(--dm-bad)}
.fbx-st{font-size:12.5px;margin-left:6px}
.fbx-box>div{margin-inline:-16px;padding-inline:var(--dm-s-4)}
.fbx-in{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:10px;margin:var(--dm-s-1) 0 0}
/* the component grows with what it shows in every style (grow(), owner's notes 18 Nov), and keeps no room under the sheet:
   its shadow shows past the fold and the growing box instead. The fold's own gap goes with it when it is shut */
.fbx.growing,.fbx-box>div{overflow-clip-margin:32px}
.fbx-box{transition:grid-template-rows var(--dm-t) var(--dm-ease),opacity var(--dm-t) var(--dm-ease),margin-top var(--dm-t) var(--dm-ease)}
.fbx-box.shut{margin-top:calc(-1 * var(--dm-s-2));transition:grid-template-rows var(--dm-t) var(--dm-ease),opacity var(--dm-t) var(--dm-ease),margin-top var(--dm-t) var(--dm-ease),visibility 0s var(--dm-t)}
.fbx-q{font-size:13.5px;font-weight:500}
.fbx-ch{display:flex;flex-wrap:wrap;gap:6px}
.fbx-ch .chip.on{background:var(--dm-sel);color:var(--dm-accent-fg,var(--dm-accent));box-shadow:none}
.fbx-ta{display:block;width:100%;resize:none;border:0;outline:0;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);padding:10px var(--dm-s-3);font:inherit;font-size:13.5px;line-height:1.5;color:var(--dm-fg);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.fbx-ta{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.fbx-ta:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.fbx-ta::placeholder{color:var(--dm-muted)}
/* the footer sits under a hairline in Soft and Blueprint (owner, 21 Nov), 12px from it on each side; Clean's is a foot strip */
.fbx-f{display:flex;align-items:center;gap:6px;margin-top:var(--dm-s-1);padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.fbx-n{font-size:12px;flex:1;min-width:0}
/* sent: a neutral line with the green tick, no green fill (owner, 18 Nov: a finished state) */
.fbx-thx{display:flex;align-items:center;gap:var(--dm-s-2);font-size:13px;line-height:20px;color:var(--dm-fg2)}
.fbx-thx svg{flex:none;color:var(--dm-ok-mark)}
@media (max-width:480px){.fbx-n{display:none}}
/* Clean (owner, 18 Nov): the sheet's content sits 16px in from its edges, and its foot is an off-white strip: the note
   starts where the question does, and Cancel and Send are 28px pills 16px from the card's edges and the strip's hairline (owner, 23 Nov).
   The first thumb's icon starts where the answer and the sheet do. The chrome is monochrome: a rated
   thumb fills in ink (no red fill, no tilt) and a picked reason is an ink chip like a toggle that is on */
:root[data-style="clean"] .fbx-bar .ib.on svg,:root [data-style="clean"] .fbx-bar .ib.on svg,:root [data-style="clean"].fbx-bar .ib.on svg{transform:none}
:root[data-style="clean"] .fbx-bar .ib.on,:root [data-style="clean"] .fbx-bar .ib.on,:root [data-style="clean"].fbx-bar .ib.on{background:none;color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .fbx-bar .ib.on:hover,:root [data-style="clean"] .fbx-bar .ib.on:hover,:root [data-style="clean"].fbx-bar .ib.on:hover{background:var(--dm-row)}}
:root[data-style="clean"] .fbx-bar .ib.on svg,:root [data-style="clean"] .fbx-bar .ib.on svg,:root [data-style="clean"].fbx-bar .ib.on svg{fill:currentColor}
:root[data-style="clean"] .fbx-in.panel,:root [data-style="clean"] .fbx-in.panel,:root [data-style="clean"].fbx-in.panel{gap:12px;margin:4px 0 0;padding:16px 16px 0;overflow:clip}
:root[data-style="clean"] .fbx-q,:root [data-style="clean"] .fbx-q,:root [data-style="clean"].fbx-q{font-size:14px;line-height:20px}
:root[data-style="clean"] .fbx-ch .chip.on,:root [data-style="clean"] .fbx-ch .chip.on,:root [data-style="clean"].fbx-ch .chip.on{background:var(--dm-btn-2);color:var(--dm-on-btn);box-shadow:inset 0 0 0 1px var(--dm-btn-2)}
/* a reason not picked takes the one hover over its fill, easing over 220ms (owner, 21 Nov) */
:root[data-style="clean"] .fbx-ch .chip,:root [data-style="clean"] .fbx-ch .chip,:root [data-style="clean"].fbx-ch .chip{transition:background-color var(--dm-t-fast) var(--dm-ease),box-shadow var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .fbx-ch .chip:not(.on):hover,:root [data-style="clean"] .fbx-ch .chip:not(.on):hover,:root [data-style="clean"].fbx-ch .chip:not(.on):hover{background:var(--dm-chip);box-shadow:inset 0 0 0 99px var(--dm-row)}}
:root[data-style="clean"] .fbx-f,:root [data-style="clean"] .fbx-f,:root [data-style="clean"].fbx-f{gap:8px;margin:4px -16px 0;padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-top:1px solid var(--dm-line)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .fbx-f .pill.ghost:hover,:root [data-style="clean"] .fbx-f .pill.ghost:hover,:root [data-style="clean"].fbx-f .pill.ghost:hover{background:var(--dm-row)}}
/* the note keeps to one line, so the strip stays one control tall */
:root[data-style="clean"] .fbx-n,:root [data-style="clean"] .fbx-n,:root [data-style="clean"].fbx-n{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* on a phone the note gives way, and Cancel and Send keep to the right edge */
:root[data-style="clean"] .fbx-x,:root [data-style="clean"] .fbx-x,:root [data-style="clean"].fbx-x{margin-left:auto}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, REDUCE, enter, grow, html, swap } from '../core/core.js';
DM.def('feedback-sheet', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{up}', I('up-thumb')).replace('{dn}', I('down-thumb'));
  const up = $('.fbx-up', r), dn = $('.fbx-dn', r), box = $('.fbx-box', r), st = $('.fbx-st', r), go = $('.fbx-go', r), ta = $('.fbx-ta', r), chips = $$('.fbx-ch .chip', r);
  // the component grows with what it shows in every style (grow(), once its entrance has settled), so the thanks line
  // eases in as the sheet folds away
  const fbx = $('.fbx', r);
  Promise.resolve().then(() => Promise.all(fbx.getAnimations().map(a => a.finished.catch(() => {})))).then(() => { if (!c.dead && fbx.isConnected) c.offs.push(grow(fbx)); });
  const ready = () => go.disabled = !(chips.some(x => x.classList.contains('on')) || ta.value.trim());
  chips.forEach(ch => ch.onclick = () => { ch.classList.toggle('on'); ready(); });
  ta.oninput = ready;
  up.onclick = () => { const on = !up.classList.contains('on'); up.classList.toggle('on', on); dn.classList.remove('on'); box.classList.add('shut'); swap(st, on ? 'Thanks, noted' : ''); };
  // the demo opens the sheet without taking the focus from wherever you are on the page
  const down = focus => { const on = !dn.classList.contains('on'); dn.classList.toggle('on', on); up.classList.remove('on'); box.classList.toggle('shut', !on); swap(st, ''); if (on && focus) c.later(350, () => ta.focus({ preventScroll:true })); };
  dn.onclick = e => down(e.isTrusted);
  $('.fbx-x', r).onclick = () => { box.classList.add('shut'); dn.classList.remove('on'); };
  go.onclick = () => c.run(async () => {
    // the button is as wide as what it shows, and eases to the spinner's width
    const w0 = go.offsetWidth; go.innerHTML = '<span class="spin"></span>'; const w1 = go.offsetWidth;
    if (!REDUCE && w0 !== w1) go.animate([{ width:w0 + 'px' }, { width:w1 + 'px' }], { duration:220, easing:'cubic-bezier(.23,1,.32,1)' });
    await c.wait(800);
    box.classList.add('shut'); await c.wait(300);
    const n = chips.filter(x => x.classList.contains('on')).length;
    const thx = html(`<div class="fbx-thx">${I('ok')}<span>Thanks. The agent will ${n ? 'avoid this' : 'use this'} next time in this project.</span></div>`);
    ($(':scope>.dm-grow', fbx) || fbx).appendChild(thx); enter(thx); swap(st, '');
  });
  /* once it has entered, it rates the answer down and fills in the sheet by itself. Clicking, focusing or typing in it
     takes over, and what it had typed goes */
  c.run(async () => {
    await c.step(1500); down(false);
    await c.step(1000); chips[1].click();
    await c.step(700);
    await c.type(ta, 'Keep our 8px spacing scale', { ms:() => 34 + Math.random() * 40, each:ready, keep:true });
    await c.step(650); go.click();
  });
});
